-- handwritten: runtime/server/mixins/Ped.lua

do

local CreatePed = CreatePed

-- the CREATE_PED server setter ignores pedType and the network flags
---@param model fx.Model|integer|string
---@param position vector3|vector4
---@param heading? number
---@param options? fx.ServerPedCreateOptions
---@return fx.Ped?
statics.createRaw = function(model, position, heading, options)
  local hash = rt.hash(model)
  local h = CreatePed(options and options.pedType or 4, hash, position.x, position.y, position.z,
    rt.heading(position, heading), true, true)
  local p = T.wrap(h)
  if p then rt.applyServerOptions(p, options) end
  return p
end

statics.createAsync = rt.makeCreate("Ped.createAsync", statics.createRaw)

end

return rt.finalize(T)
